dlgs = [w for w in QApplication.topLevelWidgets() if w.__class__.__name__ == 'GeoImportDialog' and w.isVisible()]
if not dlgs:
    result = {'ok': False, 'error': 'visible GeoImportDialog not found'}
else:
    dlg = dlgs[-1]
    dlg.show()
    dlg.raise_()
    dlg.activateWindow()
    dlg.show_disclaimer()
    result = {'ok': True, 'used_dialog': repr(dlg)}"}

